    """
    Calculate the total number of business days across multiple date ranges for a
    given country, excluding weekends and public holidays.

    Parameters:
    date_ranges (list[tuple]): A list of (start_date, end_date) tuples. Each date
        may be a datetime.datetime, datetime.date, or a parseable date string.
    country (str): ISO country code used to determine public holidays. Default 'US'.

    Returns:
    int: Total count of business days across all provided date ranges (inclusive
        of both start and end dates).

    Raises:
    ValueError: If date_ranges is not iterable or a range is not a 2-item tuple.
    """
    if date_ranges is None:
        raise ValueError("date_ranges must be provided")
    try:
        ranges = list(date_ranges)
    except TypeError:
        raise ValueError("date_ranges must be an iterable of (start, end) tuples")

    years = set()
    parsed = []
    for rng in ranges:
